const EMBEDDED_INDEX = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Moniepoint BRM Live Dashboard</title>\n<link rel=\"preconnect\" href=\"https://cdn.plot.ly\">\n<script src=\"https://cdn.plot.ly/plotly-2.35.2.min.js\"></script>\n<style>\n:root{\n  --bg:#f6f8fb; --surface:#ffffff; --surface2:#f0f4fa; --ink:#0b1220; --muted:#667085; --line:#d9e1ec;\n  --blue:#1863dc; --blue2:#e8f1ff; --green:#079455; --green2:#e7f8ef; --red:#d92d20; --red2:#fff0ee; --amber:#b54708; --amber2:#fff6e6;\n  --purple:#5925dc; --shadow:0 20px 60px rgba(16,24,40,.08); --radius:22px;\n}\n*{box-sizing:border-box} body{margin:0;background:linear-gradient(180deg,#fff 0,#f6f8fb 36%,#eef3fa 100%);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}\n.shell{max-width:1500px;margin:0 auto;padding:26px}.topbar{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}.title h1{margin:0;font-size:34px;letter-spacing:-.04em;line-height:1.05}.title p{margin:8px 0 0;color:var(--muted);font-size:15px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;background:#fff;border:1px solid var(--line);border-radius:18px;padding:10px;box-shadow:var(--shadow)}\nselect,input,button{border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--ink);padding:10px 12px;font-weight:650}button{cursor:pointer}button.primary{background:var(--blue);color:white;border-color:var(--blue)}button:hover{border-color:var(--blue)}.hint{font-size:12px;color:var(--muted);margin-top:8px;text-align:right}.layout{display:grid;gap:16px}.cards{grid-template-columns:repeat(5,minmax(0,1fr));align-items:stretch}.productCards{grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch}.card,.panel{background:rgba(255,255,255,.92);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.card{padding:18px;min-height:136px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}.clickableCard{cursor:pointer;transition:transform .15s ease,border-color .15s ease}.clickableCard:hover{transform:translateY(-2px);border-color:var(--blue)}.clickHint{position:relative;margin-top:8px;color:var(--blue);font-size:12px;font-weight:800}.card:before{content:\"\";position:absolute;right:-38px;top:-42px;width:112px;height:112px;border-radius:50%;background:var(--blue2)}.card .k{position:relative;color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.card .v{position:relative;margin-top:12px;font-size:clamp(24px,2.05vw,31px);font-weight:850;letter-spacing:-.04em;line-height:1.05;white-space:normal;overflow-wrap:anywhere}.card .s{position:relative;margin-top:8px;font-size:13px;color:var(--muted)}.status{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;font-size:12px;font-weight:800}.good{color:var(--green);background:var(--green2)}.bad{color:var(--red);background:var(--red2)}.warn{color:var(--amber);background:var(--amber2)}\n.main{grid-template-columns:1.35fr .65fr}.panel{padding:18px}.panelHead{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.panel h2{font-size:18px;letter-spacing:-.02em;margin:0}.panel p{margin:4px 0 0;color:var(--muted);font-size:13px}.chart{height:360px}.sideStack{display:grid;gap:16px}.selectedBox{padding:18px;background:linear-gradient(135deg,#0b1220,#152238);color:white;border-radius:var(--radius);box-shadow:var(--shadow)}.selectedBox .muted{color:#b8c5d8}.selectedGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.mini{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);padding:11px;border-radius:14px}.mini b{display:block;font-size:18px;margin-top:3px}.two{grid-template-columns:1fr 1fr}.tableWrap{max-height:420px;overflow:auto;border-radius:16px;border:1px solid var(--line)}table{width:100%;border-collapse:collapse;font-size:13px;background:white;table-layout:fixed}th,td{padding:11px 12px;border-bottom:1px solid #edf1f7;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;vertical-align:middle}th{position:sticky;top:0;background:#f8fafc;color:#475467;z-index:1;font-size:12px;text-transform:uppercase;letter-spacing:.05em}td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}.tableWrap table{min-width:860px}.daily-report-table{min-width:1040px}.daily-report-table th:nth-child(1),.daily-report-table td:nth-child(1){width:120px}.daily-report-table th:nth-child(2),.daily-report-table td:nth-child(2){width:90px}.daily-report-table th:nth-child(3),.daily-report-table td:nth-child(3){width:85px}.daily-report-table th:nth-child(4),.daily-report-table td:nth-child(4){width:105px}.daily-report-table th:nth-child(5),.daily-report-table td:nth-child(5),.daily-report-table th:nth-child(6),.daily-report-table td:nth-child(6){width:88px}.daily-report-table th:nth-child(7),.daily-report-table td:nth-child(7){width:170px}.daily-report-table th:nth-child(8),.daily-report-table td:nth-child(8){width:105px}tr.clickable{cursor:pointer}tr.clickable:hover{background:#eef5ff}.note{border-left:4px solid var(--blue);background:#eef5ff;padding:12px 14px;border-radius:12px;color:#1d3763;font-size:13px}.footer{margin:20px 0 0;text-align:center;color:var(--muted);font-size:12px}@media(max-width:1200px){.cards{grid-template-columns:repeat(3,minmax(0,1fr))}.productCards{grid-template-columns:repeat(3,minmax(0,1fr))}.main,.two{grid-template-columns:1fr}}@media(max-width:980px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.productCards{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:720px){.shell{padding:14px}.topbar{display:block}.toolbar{margin-top:14px}.cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.productCards{grid-template-columns:1fr}.card{padding:14px;min-height:124px}.card .v{font-size:26px}.card .s{font-size:12px}.chart{height:330px}}@media(max-width:430px){.cards{grid-template-columns:1fr}.card{min-height:112px}}\n</style>\n</head>\n<body><div class=\"shell\">\n  <div class=\"topbar\"><div class=\"title\"><h1>Moniepoint BRM Live Dashboard</h1><p>Clear KPI command center: click charts, filter weeks, inspect daily reports, and track coverage.</p></div><div><div class=\"toolbar\"><select id=\"weekSelect\"></select><select id=\"monthSelect\"></select><input id=\"fromDate\" type=\"date\" title=\"From date\"><input id=\"toDate\" type=\"date\" title=\"To date\"><input id=\"search\" placeholder=\"Search daily table\u2026\"><button id=\"applyDates\" class=\"primary\">Apply dates</button><button id=\"latest\">Latest week</button><button id=\"reset\">Reset view</button></div><div class=\"hint\">Calendar filter: select week, month, or date range. Charts are clickable and zoomable.</div></div></div>\n  <div class=\"layout cards\" id=\"cards\"></div>\n  <section class=\"panel\" style=\"margin-top:16px\"><div class=\"panelHead\"><div><h2>Product KPIs</h2><p>Loans, Fixed Deposit, and Moniebook active counts from latest product reports.</p></div><span class=\"status good\" id=\"productDateBadge\"></span></div><div class=\"layout productCards\" id=\"productCards\"></div><div class=\"tableWrap\" id=\"productTable\" style=\"margin-top:14px\"></div></section>\n  <div class=\"layout main\" style=\"margin-top:16px\"><section class=\"panel\"><div class=\"panelHead\"><div><h2>Weekly Performance</h2><p>Click any point/bar to focus that week.</p></div><span id=\"coverageBadge\" class=\"status warn\"></span></div><div id=\"weeklyChart\" class=\"chart\"></div></section><aside class=\"sideStack\"><div id=\"selected\" class=\"selectedBox\"></div><section class=\"panel\"><div class=\"panelHead\"><div><h2>Quick Reading</h2><p>What this dashboard is saying now.</p></div></div><div id=\"insights\" class=\"note\"></div></section></aside></div>\n  <div class=\"layout two\" style=\"margin-top:16px\"><section class=\"panel\"><div class=\"panelHead\"><div><h2>Daily KPI Trend</h2><p>Updates when you change week. Click a date to inspect.</p></div></div><div id=\"dailyChart\" class=\"chart\"></div></section><section class=\"panel\"><div class=\"panelHead\"><div><h2>Terminals: Active vs Inactive</h2><p>Whole-number terminal KPIs.</p></div></div><div id=\"terminalChart\" class=\"chart\"></div></section></div>\n  <div class=\"layout two\" style=\"margin-top:16px\"><section class=\"panel\"><div class=\"panelHead\"><div><h2>Weekly KPI Table</h2><p>Click a row to focus that week.</p></div></div><div class=\"tableWrap\" id=\"weeklyTable\"></div></section><section class=\"panel\"><div class=\"panelHead\"><div><h2>Report Coverage</h2><p>Shows complete vs partial reporting weeks.</p></div></div><div class=\"tableWrap\" id=\"coverageTable\"></div></section></div>\n  <section class=\"panel\" style=\"margin-top:16px\"><div class=\"panelHead\"><div><h2>Daily Reports</h2><p>Searchable latest daily report table.</p></div></div><div class=\"tableWrap\" id=\"dailyTable\"></div></section>\n  <div class=\"footer\" id=\"footer\">Loading\u2026</div>\n</div>\n<script>\nlet weekly=[], daily=[], productKpis={reports:[]}, detailLinks={}, selectedDate=null;\nconst naira=new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}); const nfmt=new Intl.NumberFormat('en-US');\nconst pct=v=>Number(v||0).toFixed(2)+'%'; const n=v=>nfmt.format(Math.round(Number(v)||0)); const moneyShort=v=>{v=Number(v)||0; if(Math.abs(v)>=1e9) return '\u20a6'+(v/1e9).toFixed(2)+'B'; if(Math.abs(v)>=1e6) return '\u20a6'+(v/1e6).toFixed(1)+'M'; return naira.format(v)}; const gap=v=>(Number(v)>=0?'+':'')+Number(v||0).toFixed(2)+' pts'; const cls=v=>Number(v)>=0?'good':'bad';\nlet filterMode='week';\nfunction week(){return document.getElementById('weekSelect').value || weekly.at(-1)?.week_label}\nfunction wrow(label=week()){return weekly.find(w=>w.week_label===label)||weekly.at(-1)}\nfunction monthKey(date){return String(date||'').slice(0,7)}\nfunction currentMonth(){return document.getElementById('monthSelect')?.value || monthKey(daily.at(-1)?.report_date_iso)}\nfunction dateInRange(date, from, to){return (!from || date>=from) && (!to || date<=to)}\nfunction filteredDaily(){\n  const from=document.getElementById('fromDate')?.value||''; const to=document.getElementById('toDate')?.value||'';\n  if(filterMode==='month') return daily.filter(d=>monthKey(d.report_date_iso)===currentMonth());\n  if(filterMode==='range') return daily.filter(d=>dateInRange(d.report_date_iso,from,to));\n  return daily.filter(d=>d.week_label===week());\n}\nfunction filteredWeekly(){\n  const rows=filteredDaily(); if(filterMode==='week') return weekly;\n  const labels=[...new Set(rows.map(d=>d.week_label))]; return weekly.filter(w=>labels.includes(w.week_label));\n}\nfunction activePeriodLabel(){\n  if(filterMode==='month') return currentMonth();\n  if(filterMode==='range') return `${document.getElementById('fromDate').value||'start'} \u2192 ${document.getElementById('toDate').value||'end'}`;\n  return week();\n}\nfunction vals(rows,key){return rows.map(r=>r[key]).filter(v=>v!==''&&v!==null&&v!==undefined).map(v=>Number(v)).filter(v=>Number.isFinite(v))}\nfunction avg(rows,key){const v=vals(rows,key);return v.length?v.reduce((a,b)=>a+b,0)/v.length:0}\nfunction sum(rows,key){const v=vals(rows,key);return v.reduce((a,b)=>a+b,0)}\nfunction periodSummary(){\n  if(filterMode==='week') return wrow();\n  const rows=filteredDaily();\n  const label=activePeriodLabel();\n  if(!rows.length){return {week_label:label,period_start:'',period_end:'',days_available:0,'avg_TA_%':0,'TA_target_%':72,TA_gap_pts:-72,'avg_Top_BO_retention_%':0,'Top_BO_retention_target_%':92,retention_gap_pts:-92,avg_total_terminal_count:0,avg_assigned_terminal_count:0,avg_unassigned_terminals:0,avg_active_terminals:0,avg_inactive_count:0,avg_inactive_terminals_below_100k_7_days:0,avg_non_transacting_terminals:0,weekly_transaction_value:0,weekly_transaction_volume:0,weekly_transaction_value_wow_change:0,weekly_transaction_volume_wow_change:0}}\n  const ta=avg(rows,'TA_%'), ret=avg(rows,'Top_BO_retention_%');\n  return {week_label:label,period_start:rows[0].report_date_iso,period_end:rows.at(-1).report_date_iso,days_available:rows.length,'avg_TA_%':ta,'TA_target_%':72,TA_gap_pts:ta-72,'avg_Top_BO_retention_%':ret,'Top_BO_retention_target_%':92,retention_gap_pts:ret-92,avg_total_terminal_count:Math.round(avg(rows,'total_terminal_count')),avg_assigned_terminal_count:Math.round(avg(rows,'terminals_assigned_to_bos')),avg_unassigned_terminals:Math.round(avg(rows,'unassigned_terminals')),avg_active_terminals:Math.round(avg(rows,'active_terminals_payment_above_100k_7_days')),avg_inactive_count:Math.round(avg(rows,'inactive_terminals_payment_below_100k_7_days')),avg_active_terminals_payment_above_100k_7_days:Math.round(avg(rows,'active_terminals_payment_above_100k_7_days')),avg_inactive_terminals_payment_below_100k_7_days:Math.round(avg(rows,'inactive_terminals_payment_below_100k_7_days')),avg_non_transacting_terminals:Math.round(avg(rows,'non_transacting_terminals')),weekly_transaction_value:sum(rows,'daily_total_transaction_value'),weekly_transaction_volume:sum(rows,'daily_total_transaction_volume'),weekly_transaction_value_wow_change:0,weekly_transaction_volume_wow_change:0}\n}\nfunction initControls(){\n const sel=document.getElementById('weekSelect');\n sel.innerHTML=weekly.map(w=>`<option>${w.week_label}</option>`).join('');\n sel.value=weekly.at(-1).week_label;\n const months=[...new Set(daily.map(d=>monthKey(d.report_date_iso)))];\n const ms=document.getElementById('monthSelect');\n ms.innerHTML=months.map(m=>`<option value=\"${m}\">${m}</option>`).join(''); ms.value=months.at(-1)||'';\n document.getElementById('fromDate').value=daily.at(-7)?.report_date_iso || daily.at(0)?.report_date_iso || '';\n document.getElementById('toDate').value=daily.at(-1)?.report_date_iso || '';\n sel.onchange=()=>{filterMode='week';selectedDate=null;render()};\n ms.onchange=()=>{filterMode='month';selectedDate=null;render()};\n document.getElementById('applyDates').onclick=()=>{filterMode='range';selectedDate=null;render()};\n document.getElementById('latest').onclick=()=>{filterMode='week';sel.value=weekly.at(-1).week_label;selectedDate=null;render()};\n document.getElementById('reset').onclick=()=>{filterMode='week';sel.value=weekly.at(-1).week_label;ms.value=months.at(-1)||'';document.getElementById('search').value='';selectedDate=null;render()};\n document.getElementById('search').oninput=renderTables\n}\nfunction renderProductKpis(){\n const reports=productKpis.reports||[];\n document.getElementById('productDateBadge').textContent='Latest: '+(productKpis.latest_report_date||'');\n document.getElementById('productCards').innerHTML=reports.map(r=>`<div class=\"card ${r.detail_url?'clickableCard':''}\" ${r.detail_url?`onclick=\"window.open('${r.detail_url}','_blank')\" title=\"Open clean Google Sheets contact list\"`:''}><div class=\"k\">${r.product}</div><div class=\"v\">${n(r.active_count)}</div><div class=\"s\">${r.primary_label}<br><span class=\"status good\">${r.report_date}</span></div>${r.detail_url?'<div class=\"clickHint\">Click to view clean contact list \u2192</div>':''}</div>`).join('');\n document.getElementById('productTable').innerHTML=table(['Product','Report Date','Active','Main KPI','Other Details'],reports.map(r=>{const details=Object.entries(r.secondary_metrics||{}).map(([k,v])=>`${k}: ${typeof v==='number'?n(v):v}`).join(' \u00b7 ');return `<tr><td>${r.detail_url?`<a href=\"${r.detail_url}\" target=\"_blank\">${r.product}</a>`:r.product}</td><td>${r.report_date}</td><td class=\"num\">${n(r.active_count)}</td><td>${r.primary_label}</td><td>${details}</td></tr>`}));\n}\nfunction renderCards(w){const cards=[\n ['Terminal Activity',pct(w['avg_TA_%']),`Target ${pct(w['TA_target_%'])} \u00b7 <span class=\"status ${cls(w.TA_gap_pts)}\">${gap(w.TA_gap_pts)}</span>`,null],\n ['Retention',pct(w['avg_Top_BO_retention_%']),`Target ${pct(w['Top_BO_retention_target_%'])} \u00b7 <span class=\"status ${cls(w.retention_gap_pts)}\">${gap(w.retention_gap_pts)}</span>`,null],\n ['Total terminals',n(w.avg_total_terminal_count),`${filterMode==='week'?'Current week average':'Selected period average'} from daily reports`,null],\n ['Assigned terminals',n(w.avg_assigned_terminal_count),`${filterMode==='week'?'Current week average':'Selected period average'} from daily reports`,null],\n ['Unassigned terminals',n(w.avg_unassigned_terminals),'Total terminals minus assigned terminals',null],\n ['Active terminals',n(w.avg_active_terminals),`Payment value >\u20a6100k over 7 days<br><span class=\"clickHint\">Click to view clean active terminal contacts \u2192</span>`,detailLinks.activeTerminals],\n ['Inactive terminals',n(w.avg_inactive_count),`Payment value <\u20a6100k over 7 days<br>${filterMode==='week'?'Current week average':'Selected period average'}`,null],\n ['Non-transacting',n(w.avg_non_transacting_terminals),`No transaction for 7+ days<br><span class=\"clickHint\">Click to view sorted follow-up sheet \u2192</span>`,detailLinks.nonTransactingTerminals||detailLinks.inactiveTerminals],\n ['Txn value',moneyShort(w.weekly_transaction_value),`Full: ${naira.format(w.weekly_transaction_value)}<br>WoW <span class=\"status ${cls(w.weekly_transaction_value_wow_change||0)}\">${moneyShort(w.weekly_transaction_value_wow_change||0)}</span>`,null],\n ['Txn volume',n(w.weekly_transaction_volume),`WoW <span class=\"status ${cls(w.weekly_transaction_volume_wow_change||0)}\">${n(w.weekly_transaction_volume_wow_change||0)}</span>`,null]\n];document.getElementById('cards').innerHTML=cards.map(c=>`<div class=\"card ${c[3]?'clickableCard':''}\" ${c[3]?`onclick=\"window.open('${c[3]}','_blank')\" title=\"Open clean Google Sheets contact list\"`:''}><div class=\"k\">${c[0]}</div><div class=\"v\">${c[1]}</div><div class=\"s\">${c[2]}</div></div>`).join('');document.getElementById('coverageBadge').className='status '+(w.days_available>=7?'good':'warn');document.getElementById('coverageBadge').textContent=`${activePeriodLabel()} \u00b7 ${w.days_available} day${w.days_available==1?'':'s'} available`}\nfunction renderSelected(w){const dd=selectedDate?daily.find(d=>d.report_date_iso===selectedDate):null;document.getElementById('selected').innerHTML=`<div class=\"muted\">Selected ${dd?'date':(filterMode==='week'?'week':'period')}</div><h2 style=\"margin:6px 0 0\">${dd?dd.report_date_iso:w.week_label}</h2><p class=\"muted\" style=\"margin:4px 0 0\">${dd?dd.week_label:(w.period_start+' \u2192 '+w.period_end)}</p><div class=\"selectedGrid\"><div class=\"mini\">Terminal Activity<b>${pct(dd?dd['TA_%']:w['avg_TA_%'])}</b></div><div class=\"mini\">Retention<b>${pct(dd?dd['Top_BO_retention_%']:w['avg_Top_BO_retention_%'])}</b></div><div class=\"mini\">Total Terminals<b>${n(dd?dd.total_terminal_count:w.avg_total_terminal_count)}</b></div><div class=\"mini\">Assigned<b>${n(dd?dd.terminals_assigned_to_bos:w.avg_assigned_terminal_count)}</b></div><div class=\"mini\">Unassigned<b>${n(dd?dd.unassigned_terminals:w.avg_unassigned_terminals)}</b></div><div class=\"mini\">Active<b>${n(dd?dd.active_terminals_payment_above_100k_7_days:w.avg_active_terminals)}</b></div><div class=\"mini\">Inactive <small>(&lt;\u20a6100k)</small><b>${n(dd?dd.inactive_terminals_payment_below_100k_7_days:w.avg_inactive_count)}</b></div><div class=\"mini\">Non-transacting<b>${n(dd?dd.non_transacting_terminals:w.avg_non_transacting_terminals)}</b></div><div class=\"mini\" style=\"grid-column:1/-1\">Value<b>${naira.format(dd?dd.daily_total_transaction_value:w.weekly_transaction_value)}</b></div></div>`}\nfunction renderInsights(w){let msg=[];msg.push(`Terminal Activity is ${pct(w['avg_TA_%'])}, ${Math.abs(w.TA_gap_pts).toFixed(2)} points ${w.TA_gap_pts<0?'below':'above'} target.`);msg.push(`Retention is ${pct(w['avg_Top_BO_retention_%'])}, ${Math.abs(w.retention_gap_pts).toFixed(2)} points ${w.retention_gap_pts<0?'below':'above'} target.`);msg.push(`Terminal formula: Total = Active + Inactive + Non-transacting + Unassigned. Active/inactive use payment value only; transfers are excluded.`);if(w.days_available<7)msg.push(`${w.week_label} is partial: ${w.days_available} daily reports available.`);else if(filterMode!=='week')msg.push(`${w.week_label} filter is applied: ${w.days_available} daily reports included.`);document.getElementById('insights').innerHTML=msg.join('<br><br>')}\nfunction plotWeekly(){const wr=filteredWeekly();const labels=wr.map(w=>w.week_label);const data=[{x:labels,y:wr.map(w=>w['avg_TA_%']),name:'Terminal Activity %',type:'scatter',mode:'lines+markers',line:{color:'#1863dc',width:4},marker:{size:10}},{x:labels,y:wr.map(w=>w['avg_Top_BO_retention_%']),name:'Retention %',type:'scatter',mode:'lines+markers',line:{color:'#079455',width:4},marker:{size:10}},{x:labels,y:wr.map(w=>w.weekly_transaction_value/1000000),name:'Txn value \u20a6m',type:'bar',marker:{color:'rgba(89,37,220,.25)'},yaxis:'y2'}];Plotly.newPlot('weeklyChart',data,{margin:{t:20,l:52,r:55,b:50},paper_bgcolor:'transparent',plot_bgcolor:'transparent',hovermode:'x unified',legend:{orientation:'h'},yaxis:{title:'Percent'},yaxis2:{title:'\u20a6m',overlaying:'y',side:'right',showgrid:false},xaxis:{title:'Week'}},{responsive:true,displaylogo:false});document.getElementById('weeklyChart').on('plotly_click',e=>{const x=e.points[0].x;document.getElementById('weekSelect').value=x;filterMode='week';selectedDate=null;render()})}\nfunction plotDaily(){const rows=filteredDaily();Plotly.newPlot('dailyChart',[{x:rows.map(r=>r.report_date_iso),y:rows.map(r=>r['TA_%']),name:'Terminal Activity %',mode:'lines+markers',type:'scatter',line:{color:'#1863dc',width:4},marker:{size:10}},{x:rows.map(r=>r.report_date_iso),y:rows.map(r=>r['Top_BO_retention_%']),name:'Retention %',mode:'lines+markers',type:'scatter',line:{color:'#079455',width:4},marker:{size:10}},{x:rows.map(r=>r.report_date_iso),y:rows.map(r=>r.daily_total_transaction_value/1000000),name:'Txn value \u20a6m',type:'bar',marker:{color:'rgba(245,158,11,.25)'},yaxis:'y2'}],{margin:{t:20,l:52,r:55,b:50},paper_bgcolor:'transparent',plot_bgcolor:'transparent',hovermode:'x unified',legend:{orientation:'h'},yaxis:{title:'Percent'},yaxis2:{title:'\u20a6m',overlaying:'y',side:'right',showgrid:false},xaxis:{title:'Date'}},{responsive:true,displaylogo:false});document.getElementById('dailyChart').on('plotly_click',e=>{selectedDate=e.points[0].x;renderSelected(periodSummary());renderTables()})}\nfunction plotTerminals(){const wr=filteredWeekly();const labels=wr.map(w=>w.week_label);Plotly.newPlot('terminalChart',[{x:labels,y:wr.map(w=>w.avg_total_terminal_count),name:'Total terminals',type:'scatter',mode:'lines+markers',line:{color:'#1863dc',width:3}},{x:labels,y:wr.map(w=>w.avg_assigned_terminal_count),name:'Assigned terminals',type:'scatter',mode:'lines+markers',line:{color:'#5925dc',width:3}},{x:labels,y:wr.map(w=>w.avg_active_terminals),name:'Active >\u20a6100k payment',type:'bar',marker:{color:'#079455'}},{x:labels,y:wr.map(w=>w.avg_inactive_count),name:'Inactive <\u20a6100k payment',type:'bar',marker:{color:'#f79009'}},{x:labels,y:wr.map(w=>w.avg_non_transacting_terminals),name:'Non-transacting 7+ days',type:'bar',marker:{color:'#d92d20'}},{x:labels,y:wr.map(w=>w.avg_unassigned_terminals),name:'Unassigned',type:'bar',marker:{color:'#667085'}}],{barmode:'group',margin:{t:20,l:52,r:20,b:50},paper_bgcolor:'transparent',plot_bgcolor:'transparent',hovermode:'x unified',legend:{orientation:'h'},yaxis:{title:'Terminals'},xaxis:{title:'Week'}},{responsive:true,displaylogo:false});document.getElementById('terminalChart').on('plotly_click',e=>{document.getElementById('weekSelect').value=e.points[0].x;filterMode='week';selectedDate=null;render()})}\nfunction table(head, rows, cls=''){const numeric=new Set(['Terminal Activity','Retention','Total','Assigned','Unassigned','Active','Inactive','Non-Transacting','Value','Volume','Days']);return `<table class=\"${cls}\"><thead><tr>${head.map(h=>`<th class=\"${numeric.has(h)?'num':''}\">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`}\nfunction renderTables(){document.getElementById('weeklyTable').innerHTML=table(['Week','Terminal Activity','Retention','Total','Assigned','Unassigned','Active','Inactive','Non-Transacting','Value','Volume'],filteredWeekly().map(r=>`<tr class=\"clickable\" onclick=\"document.getElementById('weekSelect').value='${r.week_label}';filterMode='week';selectedDate=null;render()\"><td>${r.week_label}</td><td class=\"num\">${pct(r['avg_TA_%'])}</td><td class=\"num\">${pct(r['avg_Top_BO_retention_%'])}</td><td class=\"num\">${n(r.avg_total_terminal_count)}</td><td class=\"num\">${n(r.avg_assigned_terminal_count)}</td><td class=\"num\">${n(r.avg_unassigned_terminals)}</td><td class=\"num\">${n(r.avg_active_terminals)}</td><td class=\"num\">${n(r.avg_inactive_count)}</td><td class=\"num\">${n(r.avg_non_transacting_terminals)}</td><td class=\"num\">${naira.format(r.weekly_transaction_value)}</td><td class=\"num\">${n(r.weekly_transaction_volume)}</td></tr>`));document.getElementById('coverageTable').innerHTML=table(['Week','Period','Days','Status'],weekly.map(r=>`<tr><td>${r.week_label}</td><td>${r.period_start} \u2192 ${r.period_end}</td><td class=\"num\">${r.days_available}</td><td><span class=\"status ${r.days_available>=7?'good':'warn'}\">${r.days_available>=7?'Complete':'Partial'}</span></td></tr>`));let q=(document.getElementById('search')?.value||'').toLowerCase();let rows=filteredDaily().filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q)).slice().reverse();document.getElementById('dailyTable').innerHTML=table(['Date','Week','Terminal Activity','Retention','Total','Assigned','Unassigned','Active','Inactive','Non-Transacting','Value','Volume'],rows.map(r=>`<tr class=\"clickable\" onclick=\"document.getElementById('weekSelect').value='${r.week_label}';filterMode='week';selectedDate='${r.report_date_iso}';render()\"><td>${r.report_date_iso}</td><td>${r.week_label}</td><td class=\"num\">${pct(r['TA_%'])}</td><td class=\"num\">${pct(r['Top_BO_retention_%'])}</td><td class=\"num\">${n(r.total_terminal_count)}</td><td class=\"num\">${n(r.terminals_assigned_to_bos)}</td><td class=\"num\">${n(r.unassigned_terminals)}</td><td class=\"num\">${n(r.active_terminals_payment_above_100k_7_days)}</td><td class=\"num\">${n(r.inactive_terminals_payment_below_100k_7_days)}</td><td class=\"num\">${n(r.non_transacting_terminals)}</td><td class=\"num\">${naira.format(r.daily_total_transaction_value)}</td><td class=\"num\">${n(r.daily_total_transaction_volume)}</td></tr>`),'daily-report-table')}\nfunction render(){const w=periodSummary();renderCards(w);renderProductKpis();renderSelected(w);renderInsights(w);plotWeekly();plotDaily();plotTerminals();renderTables()}\nasync function loadData(){const res=await fetch('/api/data',{cache:'no-store'});if(!res.ok)throw new Error('Could not load dashboard data');const data=await res.json();weekly=data.weekly||[];daily=data.daily||[];productKpis=data.productKpis||{reports:[]};detailLinks=data.detailLinks||{};document.getElementById('footer').textContent=`Private live dashboard \u00b7 Data generated ${data.generated_at||'now'} \u00b7 Calendar filter: week/month/date range \u00b7 Chart interactions: click, hover, zoom, legend toggle`;initControls();render()}\nloadData().catch(e=>{document.body.innerHTML=`<div style=\"padding:30px\"><h1>Dashboard failed to load</h1><p>${e.message}</p></div>`})\n</script></body></html>\n";
